#!/usr/bin/env node
/**
 * Regenerates src/api/catalog.ts from the official Telegram Ads API docs.
 *
 * Usage:
 *   node scripts/sync-catalog.mjs                    # fetch https://ads.telegram.org/docs/api
 *   node scripts/sync-catalog.mjs ./docs/api.html    # parse a local copy
 *
 * The generated file is committed, so this script is only needed when Telegram
 * ships a new API revision. Review the diff before committing.
 */

import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const DOCS_URL = "https://ads.telegram.org/docs/api";
const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = resolve(ROOT, "src/api/catalog.ts");

/** Methods that change state. Everything else is treated as a read. */
const WRITE_METHODS = new Set([
  "createAccount",
  "editAccountInfo",
  "increaseAccountBudget",
  "decreaseAccountBudget",
  "uploadAdPhoto",
  "uploadAdVideo",
  "uploadWebsitePhoto",
  "createAd",
  "editAd",
  "editAdStatus",
  "increaseAdBudget",
  "decreaseAdBudget",
  "submitAdForReview",
  "deleteAd",
  "createAudience",
  "editAudience",
  "deleteAudience",
  "createPixel",
  "createPixelEvent",
  "editPixelEvent",
  "deletePixelEvent",
]);

const DEPRECATED = new Set(["editAdStatus"]);

const stripTags = (value) => value.replace(/<[^>]+>/g, " ");
const squash = (value) => stripTags(value).replace(/\s+/g, " ").trim();
const decode = (value) =>
  value
    .replaceAll("&amp;", "&")
    .replaceAll("&lt;", "<")
    .replaceAll("&gt;", ">")
    .replaceAll("&quot;", '"')
    .replaceAll("&#39;", "'")
    .replaceAll("&nbsp;", " ");

function parseReturnType(description) {
  const array = description.match(/returns an array of ([A-Za-z0-9_]+) objects?/i);
  if (array) return `Array<${array[1]}>`;
  const single = description.match(/returns an? ([A-Za-z0-9_]+) object/i);
  if (single) return single[1];
  if (/requires no parameters/i.test(description)) return "unknown";
  return "unknown";
}

function parse(html) {
  const blocks = html.matchAll(
    /<h4><a class="anchor" name="([a-z0-9]+)"[^>]*>.*?<\/a>([A-Za-z0-9_]+)<\/h4>(.*?)(?=<h4>|<h3>|<\/div>)/gs,
  );

  const methods = [];
  const types = [];

  for (const block of blocks) {
    const id = block[1];
    const name = block[2];
    const body = block[3];
    const description = decode(squash(body.match(/<p>(.*?)<\/p>/s)?.[1] ?? ""));
    const rows = [
      ...body.matchAll(
        /<tr>\s*<td>(.*?)<\/td>\s*<td>(.*?)<\/td>\s*<td>(.*?)<\/td>(?:\s*<td>(.*?)<\/td>)?\s*<\/tr>/gs,
      ),
    ];

    if (name[0] === name[0].toUpperCase()) {
      types.push({
        name,
        description,
        fields: rows
          .map((row) => ({
            name: decode(squash(row[1])),
            type: decode(squash(row[2])),
            description: decode(squash(row[4] ?? "")),
          }))
          .filter((field) => field.name && field.name !== "Field"),
      });
      continue;
    }

    methods.push({
      id,
      name,
      description,
      returns: parseReturnType(description),
      write: WRITE_METHODS.has(name),
      deprecated: DEPRECATED.has(name) || /^Deprecated\./i.test(description),
      params: rows
        .map((row) => ({
          name: decode(squash(row[1])),
          type: decode(squash(row[2])),
          required: /^yes$/i.test(squash(row[3])),
          description: decode(squash(row[4] ?? "")),
        }))
        .filter((param) => param.name && param.name !== "Parameter"),
    });
  }

  return { methods, types };
}

function emit({ methods }) {
  const json = JSON.stringify(methods, null, 2);
  return `// Generated by scripts/sync-catalog.mjs from ${DOCS_URL}
// Do not edit by hand. Re-run the script to refresh.
import type { ApiMethod } from "./types.js";

export const API_METHODS: readonly ApiMethod[] = ${json};

export const METHOD_NAMES: readonly string[] = API_METHODS.map((method) => method.name);

const BY_NAME = new Map(API_METHODS.map((method) => [method.name, method]));

export function getMethod(name: string): ApiMethod | undefined {
  return BY_NAME.get(name);
}

export function isWriteMethod(name: string): boolean {
  return BY_NAME.get(name)?.write ?? false;
}
`;
}

const source = process.argv[2] ?? DOCS_URL;
const html = /^https?:\/\//.test(source)
  ? await (await fetch(source)).text()
  : await readFile(resolve(ROOT, source), "utf8");

const parsed = parse(html);

if (parsed.methods.length < 40) {
  console.error(`Expected at least 40 methods, parsed ${parsed.methods.length}. Aborting.`);
  process.exit(1);
}

await writeFile(OUT, emit(parsed), "utf8");
console.log(`Wrote ${parsed.methods.length} methods to ${OUT}`);
console.log(`Found ${parsed.types.length} types (not emitted; see src/api/types.ts).`);
